source='''from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]
    forms = [
        ("row", lambda r, c: r),
        ("col", lambda r, c: c),
        ("diag_down", lambda r, c: r - c),
        ("diag_up", lambda r, c: r + c),
    ]
    best = None
    for name, key_fn in forms:
        groups = defaultdict(list)
        for r, c, color in points:
            groups[key_fn(r, c)].append(color)
        if any(len(set(colors)) != 1 for colors in groups.values()):
            continue
        # Favor the direction that groups the marks into the fewest, longest
        # monochrome stripes.
        score = sum(len(colors) ** 2 for colors in groups.values())
        candidate = (score, name, key_fn, groups)
        if best is None or candidate[0] > best[0]:
            best = candidate
    if best is None:
        return [row[:] for row in grid]
    _, _, key_fn, groups = best
    clues = {key: colors[0] for key, colors in groups.items()}
    # The marks give samples of each phase of a repeating stripe pattern.
    period = None
    for p in range(1, h + w + 1):
        phase_colors = {}
        valid = True
        for key, color in clues.items():
            phase = key % p
            if phase in phase_colors and phase_colors[phase] != color:
                valid = False
                break
            phase_colors[phase] = color
        if valid and len(phase_colors) == p:
            period = p
            break
    if period is None:
        # Fallback: use the shortest consistent period available.
        for p in range(1, h + w + 1):
            phase_colors = {}
            valid = True
            for key, color in clues.items():
                phase = key % p
                if phase in phase_colors and phase_colors[phase] != color:
                    valid = False
                    break
                phase_colors[phase] = color
            if valid:
                period, phases = p, phase_colors
                break
        if period is None:
            return [row[:] for row in grid]
        # Fill missing phases with a known stripe color only for malformed inputs.
        phase_colors = {i: phases.get(i, next(iter(phases.values()))) for i in range(period)}
    else:
        phase_colors = {key % period: color for key, color in clues.items()}
    return [[phase_colors[key_fn(r, c) % period] for c in range(w)] for r in range(h)]
'''
